12	#include "aclrtlaunch_moe_group_score_aggregation_and_masking.h"
13	
14	namespace ascend_kernel {
15	
16	constexpr int32_t NUM_EXPERTS = 256;
17	constexpr int32_t N_GROUP = 8;
18	constexpr int32_t MAX_CORES = 8;
19	
20	struct MoERoutingTiling {
21	    int32_t numTokens;
22	    int32_t rowsPerCore;
23	    float   negInf;
24	};
25	
26	std::tuple<at::Tensor, at::Tensor> moe_group_score_aggregation_and_masking(
27	    const at::Tensor& scores)
28	{
29	    TORCH_CHECK(scores.dim() == 2, "scores must be 2D");
30	    TORCH_CHECK(scores.size(1) == NUM_EXPERTS, "scores last dim must be 256");
31	    TORCH_CHECK(scores.scalar_type() == at::kFloat,
32	                "scores must be float32 (wrapper handles dtype conversion)");
33	    TORCH_CHECK(scores.is_contiguous(), "scores must be contiguous");
34	
35	    int32_t numTokens = static_cast<int32_t>(scores.size(0));
36	
37	    auto* ascendCPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
38	    int32_t coreNum = static_cast<int32_t>(ascendCPlatform->GetCoreNumAiv());
39	    int32_t usedCores = std::min<int32_t>(
40	        std::min<int32_t>(coreNum, MAX_CORES), numTokens);
41	    if (usedCores < 1) usedCores = 1;
42	    int32_t rowsPerCore = (numTokens + usedCores - 1) / usedCores;
43	
44	    float negInf = -3.402823466e+38f; // effectively -inf for masking
45	
46	    at::Tensor maskedScores = at::empty_like(scores);
47	    at::Tensor groupMask = at::empty({numTokens, N_GROUP}, scores.options());
48	
49	    MoERoutingTiling tiling;
50	    tiling.numTokens = numTokens;
51	    tiling.rowsPerCore = rowsPerCore;
52	    tiling.negInf = negInf;
53	
54	    at::Tensor tilingCPU = at::empty(
55	        {static_cast<int64_t>(sizeof(MoERoutingTiling))},
56	        at::device(at::kCPU).dtype(at::kByte));
57	    std::memcpy(tilingCPU.data_ptr(), &tiling, sizeof(MoERoutingTiling));
58	    at::Tensor tilingNpu = tilingCPU.to(at::kPrivateUse1);
59	
60	    int64_t blockDim = usedCores;
61	    EXEC_KERNEL_CMD(moe_group_score_aggregation_and_masking,
62	                    blockDim, scores, maskedScores, groupMask, tilingNpu);
63	
64	    return std::make_tuple(maskedScores, groupMask);
65	}
66	
67	}  // namespace ascend_kernel
