6	#include "kernel_operator.h"
7	
8	using namespace AscendC;
9	
10	constexpr int32_t NUM_EXPERTS = 256;
11	constexpr int32_t N_GROUP = 8;
12	constexpr int32_t TOPK_GROUP = 4;
13	constexpr int32_t EXPERTS_PER_GROUP = 32;
14	
15	/* Tiling: packed struct passed from host via GM */
16	struct MoERoutingTiling {
17	    int32_t numTokens;
18	    int32_t rowsPerCore;
19	    float   negInf;
20	};
21	
22	class KernelMoeGroupScoreAggregationAndMasking {
23	public:
24	    __aicore__ inline KernelMoeGroupScoreAggregationAndMasking() {}
25	    __aicore__ inline void Init(
26	        GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
27	        GM_ADDR tilingGM, TPipe* tPipe);
28	    __aicore__ inline void Process();
29	
30	private:
31	    __aicore__ inline void CopyIn(int32_t tokenIdx);
32	    __aicore__ inline void Compute(int32_t tokenIdx);
33	    __aicore__ inline void CopyOut(int32_t tokenIdx);
34	
35	    GlobalTensor<float> scoresGm;
36	    GlobalTensor<float> maskedScoresGm;
37	    GlobalTensor<float> groupMaskOutGm;
38	
39	    int32_t numTokens;
40	    int32_t rowsPerCore;
41	    float   negInf;
42	
43	    TQue<QuePosition::VECIN, 1> inQueue;
44	    TQue<QuePosition::VECOUT, 1> outQueueScore;
45	    TQue<QuePosition::VECOUT, 1> outQueueMask;
46	    TBuf<TPosition::VECCALC> calcBuf;
47	    TPipe* pipe;
48	};
49	
50	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking::Init(
51	    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
52	    GM_ADDR tilingGM, TPipe* tPipe)
53	{
54	    this->pipe = tPipe;
55	    auto* gt = reinterpret_cast<__gm__ MoERoutingTiling*>(tilingGM);
56	    this->numTokens = gt->numTokens;
57	    this->rowsPerCore = gt->rowsPerCore;
58	    this->negInf = -3.402823466e+38f; // effectively -inf for float32
59	
60	    scoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(scores),
61	                              static_cast<int64_t>(numTokens) * NUM_EXPERTS);
62	    maskedScoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(maskedScores),
63	                                    static_cast<int64_t>(numTokens) * NUM_EXPERTS);
64	    groupMaskOutGm.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(groupMaskOut),
65	                                    static_cast<int64_t>(numTokens) * N_GROUP);
66	
67	    pipe->InitBuffer(inQueue, 1, NUM_EXPERTS * sizeof(float));
68	    pipe->InitBuffer(outQueueScore, 1, NUM_EXPERTS * sizeof(float));
69	    pipe->InitBuffer(outQueueMask, 1, N_GROUP * sizeof(float));
70	    pipe->InitBuffer(calcBuf, (NUM_EXPERTS * 4 + 512) * static_cast<int64_t>(sizeof(float)));
71	}
72	
73	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking::Process()
74	{
75	    int32_t coreIdx = static_cast<int32_t>(GetBlockIdx());
76	    for (int32_t localIdx = 0; localIdx < rowsPerCore; ++localIdx) {
77	        int32_t tokenIdx = coreIdx * rowsPerCore + localIdx;
78	        if (tokenIdx >= numTokens) break;
79	        CopyIn(tokenIdx);
80	        Compute(tokenIdx);
81	        CopyOut(tokenIdx);
82	    }
83	}
84	
85	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking::CopyIn(
86	    int32_t tokenIdx)
87	{
88	    LocalTensor<float> inLocal = inQueue.AllocTensor<float>();
89	    int64_t offset = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
90	    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(float)), 0, 0, 0};
91	    DataCopyPadExtParams<float> pp{false, 0, 0, 0};
92	    DataCopyPad(inLocal, scoresGm[offset], cp, pp);
93	    inQueue.EnQue(inLocal);
94	}
95	
96	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking::Compute(
97	    int32_t tokenIdx)
98	{
99	    LocalTensor<float> buf = calcBuf.Get<float>(NUM_EXPERTS * 5 + 128);
100	    LocalTensor<float> inLocal = inQueue.DeQue<float>();
101	
102	    // sfp32 at offset 0 (256), output at offset 512 (256),
103	    // groupScores at offset 1024, groupMask at offset 1152
104	    // Extra 512 padding between regions to avoid any aliasing
105	    LocalTensor<float> sfp32 = buf;
106	    DataCopy(sfp32, inLocal, NUM_EXPERTS);
107	    constexpr int32_t OFF_OUT = NUM_EXPERTS * 2;           // 512
108	    constexpr int32_t OFF_GS  = NUM_EXPERTS * 4;           // 1024
109	    constexpr int32_t OFF_GM  = OFF_GS + 64;                // 1088
110	    LocalTensor<float> outputFp32 = buf[OFF_OUT];
111	    LocalTensor<float> groupScores = buf[OFF_GS];
112	    LocalTensor<float> groupMask = buf[OFF_GM];
113	
114	    // ============================================================
115	    // Top-2 per group (8 groups × 32 elements)
116	    // ============================================================
117	    for (int32_t g = 0; g < N_GROUP; ++g) {
118	        int32_t base = g * EXPERTS_PER_GROUP;
119	        float best1 = -3.402823466e+38f;
120	        float best2 = -3.402823466e+38f;
121	        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
122	            float v = sfp32.GetValue(base + i);
123	            if (v > best1) {
124	                best2 = best1;
125	                best1 = v;
126	            } else if (v > best2) {
127	                best2 = v;
128	            }
129	        }
130	        groupScores.SetValue(g, best1 + best2);
131	    }
132	
133	    // ============================================================
134	    // Top-4 groups
135	    // ============================================================
136	    bool selected[N_GROUP] = {false, false, false, false, false, false, false, false};
137	    for (int32_t k = 0; k < TOPK_GROUP; ++k) {
138	        float bestVal = -3.402823466e+38f;
139	        int32_t bestIdx = 0;
140	        for (int32_t g = 0; g < N_GROUP; ++g) {
141	            if (selected[g]) continue;
142	            float v = groupScores.GetValue(g);
143	            if (v > bestVal) { bestVal = v; bestIdx = g; }
144	        }
145	        selected[bestIdx] = true;
146	    }
147	
148	    // ============================================================
149	    // Build mask and output
150	    // ============================================================
151	    Duplicate(groupMask, 0.0f, N_GROUP);
152	    for (int32_t g = 0; g < N_GROUP; ++g) {
153	        if (selected[g]) groupMask.SetValue(g, 1.0f);
154	    }
155	
156	    Duplicate(outputFp32, this->negInf, NUM_EXPERTS);
157	    for (int32_t g = 0; g < N_GROUP; ++g) {
158	        if (selected[g]) {
159	            int32_t start = g * EXPERTS_PER_GROUP;
160	            for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
161	                outputFp32.SetValue(start + i, sfp32.GetValue(start + i));
162	            }
163	        }
164	    }
165	
166	    // Write outputs
167	    LocalTensor<float> outScoreLocal = outQueueScore.AllocTensor<float>();
168	    DataCopy(outScoreLocal, outputFp32, NUM_EXPERTS);
169	    outQueueScore.EnQue(outScoreLocal);
170	
171	    LocalTensor<float> outMaskLocal = outQueueMask.AllocTensor<float>();
172	    DataCopy(outMaskLocal, groupMask, N_GROUP);
173	    outQueueMask.EnQue(outMaskLocal);
174	    inQueue.FreeTensor(inLocal);
175	}
176	
177	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking::CopyOut(
178	    int32_t tokenIdx)
179	{
180	    int64_t offS = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
181	    int64_t offM = static_cast<int64_t>(tokenIdx) * N_GROUP;
182	
183	    LocalTensor<float> outScoreLocal = outQueueScore.DeQue<float>();
184	    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(float)), 0, 0, 0};
185	    DataCopyPad(maskedScoresGm[offS], outScoreLocal, cp);
186	    outQueueScore.FreeTensor(outScoreLocal);
187	
188	    LocalTensor<float> outMaskLocal = outQueueMask.DeQue<float>();
189	    DataCopyExtParams mcp{1, static_cast<uint32_t>(N_GROUP * sizeof(float)), 0, 0, 0};
190	    DataCopyPad(groupMaskOutGm[offM], outMaskLocal, mcp);
191	    outQueueMask.FreeTensor(outMaskLocal);
192	}
193	
194	extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking(
195	    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
196	    GM_ADDR tiling)
197	{
198	    MoERoutingTiling t;
199	    auto* gt = reinterpret_cast<__gm__ MoERoutingTiling*>(tiling);
200	    t.numTokens = gt->numTokens;
201	    t.rowsPerCore = gt->rowsPerCore;
202	    t.negInf = gt->negInf;
203	
204	    TPipe pipe;
205	    KernelMoeGroupScoreAggregationAndMasking op;
206	    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
207	    op.Process();
208	    pipe.Destroy();
209	}
