{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under CANN Open Software License Agreement Version 2.0.
 *
 * MoE Group Score Aggregation and Masking Kernel (v2)
 *
 * Template-based kernel supporting float32, float16 (half), and bfloat16.
 *
 * Key design:
 *  - For float32: all computation in float32 (no casts needed).
 *  - For half/bf16: group top-2 values found in float32 (ordering preserved),
 *    summed in float32, then cast to native T for correct rounding precision,
 *    then cast back to float32 for top-4 group selection.
 *    This ensures group scores match native dtype arithmetic.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t NUM_EXPERTS = 256;
constexpr int32_t N_GROUP = 8;
constexpr int32_t TOPK_GROUP = 4;
constexpr int32_t EXPERTS_PER_GROUP = 32;

/* Tiling: packed struct passed from host via GM */
struct MoERoutingTiling {
    int32_t numTokens;
    int32_t rowsPerCore;
};

template<typename T>
class KernelMoeGroupScoreAggregationAndMasking {
public:
    __aicore__ inline KernelMoeGroupScoreAggregationAndMasking() {}
    __aicore__ inline void Init(
        GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
        GM_ADDR tilingGM, TPipe* tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int32_t tokenIdx);
    __aicore__ inline void Compute(int32_t tokenIdx);
    __aicore__ inline void CopyOut(int32_t tokenIdx);

    // Compute sub-steps
    __aicore__ inline void ComputeGroupScoresFloat32(
        LocalTensor<float>& sfp32, LocalTensor<float>& groupScoresFp32);
    __aicore__ inline void ComputeGroupScoresHalfBf16(
        LocalTensor<float>& sfp32, LocalTensor<T>& inputT,
        LocalTensor<float>& groupScoresFp32, LocalTensor<T>& groupScoresT);

    GlobalTensor<T> scoresGm;
    GlobalTensor<T> maskedScoresGm;
    GlobalTensor<T> groupMaskOutGm;

    int32_t numTokens;
    int32_t rowsPerCore;

    TQue<QuePosition::VECIN, 1> inQueue;
    TQue<QuePosition::VECOUT, 1> outQueueScore;
    TQue<QuePosition::VECOUT, 1> outQueueMask;
    TBuf<TPosition::VECCALC> calcBuf;
    TPipe* pipe;
};

/* ================================================================
 * Init
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Init(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tilingGM, TPipe* tPipe)
{
    this->pipe = tPipe;
    auto* gt = reinterpret_cast<__gm__ MoERoutingTiling*>(tilingGM);
    this->numTokens = gt->numTokens;
    this->rowsPerCore = gt->rowsPerCore;

    scoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(scores),
                              static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    maskedScoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(maskedScores),
                                    static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    groupMaskOutGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(groupMaskOut),
                                    static_cast<int64_t>(numTokens) * N_GROUP);

    // I/O queues sized for native dtype
    pipe->InitBuffer(inQueue, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)));
    pipe->InitBuffer(outQueueScore, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)));
    pipe->InitBuffer(outQueueMask, 1, static_cast<uint32_t>(N_GROUP * sizeof(T)));

    // calcBuf: float32 working space for one row's computation.
    // Layout (in float elements):
    //   [0..255]       = sfp32 (float32 copy of input, 256 floats)
    //   [256..511]     = outputFp32 (float32 result, 256 floats)
    //   [512..519]     = groupScoresFp32 (8 floats)
    //   [520..527]     = groupMaskFp32 (8 floats)
    //   [528..783]     = expandedMaskFp32 (256 floats)
    //   [784..1039]    = tempFp32 (256 floats for select result, etc.)
    // Total: 1040 floats minimum, pad to 1088 for alignment
    constexpr int32_t FP32_ELEMS = 1088;
    pipe->InitBuffer(calcBuf, static_cast<uint32_t>(FP32_ELEMS * sizeof(float) + 256));
}

/* ================================================================
 * Process
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Process()
{
    int32_t coreIdx = static_cast<int32_t>(GetBlockIdx());
    for (int32_t localIdx = 0; localIdx < rowsPerCore; ++localIdx) {
        int32_t tokenIdx = coreIdx * rowsPerCore + localIdx;
        if (tokenIdx >= numTokens) break;
        CopyIn(tokenIdx);
        Compute(tokenIdx);
        CopyOut(tokenIdx);
    }
}

/* ================================================================
 * CopyIn: load one row in native dtype T
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::CopyIn(
    int32_t tokenIdx)
{
    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
    int64_t offset = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
    DataCopyPad(inLocal, scoresGm[offset], cp, pp);
    inQueue.EnQue(inLocal);
}

/* ================================================================
 * ComputeGroupScoresFloat32: float32 path - direct computation
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::ComputeGroupScoresFloat32(
    LocalTensor<float>& sfp32, LocalTensor<float>& groupScoresFp32)
{
    for (int32_t g = 0; g < N_GROUP; ++g) {
        int32_t base = g * EXPERTS_PER_GROUP;
        float best1 = -3.402823466e+38f;
        float best2 = -3.402823466e+38f;
        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
            float v = sfp32.GetValue(base + i);
            if (v > best1) {
                best2 = best1;
                best1 = v;
            } else if (v > best2) {
                best2 = v;
            }
        }
        groupScoresFp32.SetValue(g, best1 + best2);
    }
}

/* ================================================================
 * ComputeGroupScoresHalfBf16: half/bf16 path
 *
 * Principle: find top-2 in float32 (ordering preserved),
 * sum in float32, then cast to native T for correct rounding,
 * then cast back to float32 for top-4 selection.
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::ComputeGroupScoresHalfBf16(
    LocalTensor<float>& sfp32, LocalTensor<T>& inputT,
    LocalTensor<float>& groupScoresFp32, LocalTensor<T>& groupScoresT)
{
    for (int32_t g = 0; g < N_GROUP; ++g) {
        int32_t base = g * EXPERTS_PER_GROUP;
        // Find top-2 using float32 values (ordering is identical to T ordering)
        float best1 = -3.402823466e+38f;
        float best2 = -3.402823466e+38f;
        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
            float v = sfp32.GetValue(base + i);
            if (v > best1) {
                best2 = best1;
                best1 = v;
            } else if (v > best2) {
                best2 = v;
            }
        }
        // Sum in float32
        float sumFp32 = best1 + best2;
        // Cast to T and back to float32 for native T precision rounding
        T sumT = static_cast<T>(sumFp32);
        groupScoresT.SetValue(g, sumT);
        groupScoresFp32.SetValue(g, static_cast<float>(sumT));
    }
}

/* ================================================================
 * Compute: main computation per row
 *
 * Float32 path: all computation in float32.
 * Half/bf16 path: group top-2 sum uses native T rounding,
 *   rest in float32.
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Compute(
    int32_t tokenIdx)
{
    (void)tokenIdx;
    LocalTensor<T> inLocal = inQueue.DeQue<T>();

    // Get float32 working buffers from calcBuf
    // calcBuf elements are floats
    LocalTensor<float> bufFp32 = calcBuf.Get<float>(1088);

    constexpr int32_t OFF_SFP32 = 0;
    constexpr int32_t OFF_OUTFP32 = NUM_EXPERTS;               // 256
    constexpr int32_t OFF_GSFP32 = OFF_OUTFP32 + NUM_EXPERTS;  // 512
    constexpr int32_t OFF_GMFP32 = OFF_GSFP32 + 8;             // 520
    constexpr int32_t OFF_EXPMASK = OFF_GMFP32 + 8;            // 528
    constexpr int32_t OFF_TEMPFP32 = OFF_EXPMASK + NUM_EXPERTS; // 784

    LocalTensor<float> sfp32 = bufFp32[OFF_SFP32];
    LocalTensor<float> outputFp32 = bufFp32[OFF_OUTFP32];
    LocalTensor<float> groupScoresFp32 = bufFp32[OFF_GSFP32];
    LocalTensor<float> groupMaskFp32 = bufFp32[OFF_GMFP32];
    LocalTensor<float> expandedMaskFp32 = bufFp32[OFF_EXPMASK];
    LocalTensor<float> tempFp32 = bufFp32[OFF_TEMPFP32];

    // Cast input to float32 for computation
    Cast(sfp32, inLocal, CAST_NONE, NUM_EXPERTS);

    // ============================================================
    // Group top-2 + sum
    // ============================================================
    if constexpr (std::is_same_v<T, float>) {
        // float32: direct computation
        ComputeGroupScoresFloat32(sfp32, groupScoresFp32);
    } else {
        // half/bf16: native T rounding for group scores
        // Use the inLocal (native T buffer) as the T workspace for group scores
        LocalTensor<T> groupScoresT = inLocal; // reuse inLocal buffer (only need 8 T elements)
        ComputeGroupScoresHalfBf16(sfp32, inLocal, groupScoresFp32, groupScoresT);
    }

    // ============================================================
    // Top-4 groups from 8 group scores (float32)
    // ============================================================
    bool selected[N_GROUP] = {false, false, false, false, false, false, false, false};
    for (int32_t k = 0; k < TOPK_GROUP; ++k) {
        float bestVal = -3.402823466e+38f;
        int32_t bestIdx = 0;
        for (int32_t g = 0; g < N_GROUP; ++g) {
            if (selected[g]) continue;
            float v = groupScoresFp32.GetValue(g);
            if (v > bestVal) { bestVal = v; bestIdx = g; }
        }
        selected[bestIdx] = true;
    }

    // ============================================================
    // Build group mask (8,) and expanded score mask (256,)
    // ============================================================
    Duplicate(groupMaskFp32, 0.0f, N_GROUP);
    Duplicate(expandedMaskFp32, 0.0f, NUM_EXPERTS);
    for (int32_t g = 0; g < N_GROUP; ++g) {
        if (selected[g]) {
            groupMaskFp32.SetValue(g, 1.0f);
            int32_t start = g * EXPERTS_PER_GROUP;
            int32_t end = start + EXPERTS_PER_GROUP;
            for (int32_t i = start; i < end; ++i) {
                expandedMaskFp32.SetValue(i, 1.0f);
            }
        }
    }

    // ============================================================
    // Masked fill: output = expandedMask ? sfp32 : -inf
    // ============================================================
    constexpr float NEG_INF_FP32 = -3.402823466e+38f;

    // Build masked output: if mask == 1, use score; else use -inf
    for (int32_t i = 0; i < NUM_EXPERTS; ++i) {
        float maskVal = expandedMaskFp32.GetValue(i);
        if (maskVal > 0.5f) {
            outputFp32.SetValue(i, sfp32.GetValue(i));
        } else {
            outputFp32.SetValue(i, NEG_INF_FP32);
        }
    }

    // ============================================================
    // Write outputs to TQue
    // ============================================================
    if constexpr (std::is_same_v<T, float>) {
        // float32: direct copy
        LocalTensor<float> outScoreLocal = outQueueScore.AllocTensor<float>();
        DataCopy(outScoreLocal, outputFp32, NUM_EXPERTS);
        outQueueScore.EnQue(outScoreLocal);

        LocalTensor<float> outMaskLocal = outQueueMask.AllocTensor<float>();
        DataCopy(outMaskLocal, groupMaskFp32, N_GROUP);
        outQueueMask.EnQue(outMaskLocal);

        inQueue.FreeTensor(inLocal);
    } else {
        // half/bf16: cast back to T, then enqueue
        LocalTensor<T> outScoreLocal = outQueueScore.AllocTensor<T>();
        Cast(outScoreLocal, outputFp32, CAST_NONE, NUM_EXPERTS);
        outQueueScore.EnQue(outScoreLocal);

        LocalTensor<T> outMaskLocal = outQueueMask.AllocTensor<T>();
        Cast(outMaskLocal, groupMaskFp32, CAST_NONE, N_GROUP);
        outQueueMask.EnQue(outMaskLocal);

        inQueue.FreeTensor(inLocal);
    }
}

/* ================================================================
 * CopyOut: write one row in native dtype T
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::CopyOut(
    int32_t tokenIdx)
{
    int64_t offS = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
    int64_t offM = static_cast<int64_t>(tokenIdx) * N_GROUP;

    LocalTensor<T> outScoreLocal = outQueueScore.DeQue<T>();
    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)), 0, 0, 0};
    DataCopyPad(maskedScoresGm[offS], outScoreLocal, cp);
    outQueueScore.FreeTensor(outScoreLocal);

    LocalTensor<T> outMaskLocal = outQueueMask.DeQue<T>();
    DataCopyExtParams mcp{1, static_cast<uint32_t>(N_GROUP * sizeof(T)), 0, 0, 0};
    DataCopyPad(groupMaskOutGm[offM], outMaskLocal, mcp);
    outQueueMask.FreeTensor(outMaskLocal);
}

/* ================================================================
 * Kernel entry points - one per dtype
 * ================================================================ */

extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking_float(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tiling)
{
    TPipe pipe;
    KernelMoeGroupScoreAggregationAndMasking<float> op;
    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
    op.Process();
    pipe.Destroy();
}

extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking_half(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tiling)
{
    TPipe pipe;
    KernelMoeGroupScoreAggregationAndMasking<half> op;
    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
    op.Process();
    pipe.Destroy();
}

extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking_bfloat16(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tiling)
{
    TPipe pipe;
    KernelMoeGroupScoreAggregationAndMasking<bfloat16_t> op;
    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
    op.Process();
    pipe.Destroy();
}
