 * Host-side for MoeGroupScoreAggregationAndMasking (v2).
 * Supports float32, float16 (half), and bfloat16 natively.
 * Routes to the correct templated kernel entry based on input dtype.
 */

#include <algorithm>
#include <cstring>
#include <limits>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_moe_group_score_aggregation_and_masking_float.h"
#include "aclrtlaunch_moe_group_score_aggregation_and_masking_half.h"
#include "aclrtlaunch_moe_group_score_aggregation_and_masking_bfloat16.h"

namespace ascend_kernel {

constexpr int32_t NUM_EXPERTS = 256;
constexpr int32_t N_GROUP = 8;
constexpr int32_t MAX_CORES = 32;

struct MoERoutingTiling {
    int32_t numTokens;
    int32_t rowsPerCore;
};

std::tuple<at::Tensor, at::Tensor> moe_group_score_aggregation_and_masking(
    const at::Tensor& scores)
{
    TORCH_CHECK(scores.dim() == 2, "scores must be 2D");
    TORCH_CHECK(scores.size(1) == NUM_EXPERTS, "scores last dim must be 256");
    TORCH_CHECK(scores.is_contiguous(), "scores must be contiguous");

    auto dtype = scores.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                "scores dtype must be float32, float16, or bfloat16");

    int32_t numTokens = static_cast<int32_t>(scores.size(0));

    auto* ascendCPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendCPlatform->GetCoreNumAiv());
    int32_t usedCores = std::min<int32_t>(
        std::min<int32_t>(coreNum, MAX_CORES), numTokens);
    if (usedCores < 1) usedCores = 1;
    int32_t rowsPerCore = (numTokens + usedCores - 1) / usedCores;

    at::Tensor maskedScores = at::empty_like(scores);
    at::Tensor groupMask = at::empty({numTokens, N_GROUP}, scores.options());

    MoERoutingTiling tiling;
    tiling.numTokens = numTokens;
    tiling.rowsPerCore = rowsPerCore;

    at::Tensor tilingCPU = at::empty(
        {static_cast<int64_t>(sizeof(MoERoutingTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCPU.data_ptr(), &tiling, sizeof(MoERoutingTiling));
    at::Tensor tilingNpu = tilingCPU.to(at::kPrivateUse1);

    int64_t blockDim = static_cast<int64_t>(usedCores);

    if (dtype == at::kFloat) {
        EXEC_KERNEL_CMD(moe_group_score_aggregation_and_masking_float,
                        blockDim, scores, maskedScores, groupMask, tilingNpu);
    } else if (dtype == at::kHalf) {
        EXEC_KERNEL_CMD(moe_group_score_aggregation_and_masking_half,
                        blockDim, scores, maskedScores, groupMask, tilingNpu);
    } else {
        // bfloat16
        EXEC_KERNEL_CMD(moe_group_score_aggregation_and_masking_bfloat16,
                        blockDim, scores, maskedScores, groupMask, tilingNpu);
    }

    return std::make_tuple(maskedScores, groupMask);
}

}  // namespace ascend_kernel
