145	        float best1 = -3.402823466e+38f;
146	        float best2 = -3.402823466e+38f;
147	        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
148	            float v = sfp32.GetValue(base + i);
149	            if (v > best1) {
150	                best2 = best1;
151	                best1 = v;
152	            } else if (v > best2) {
153	                best2 = v;
154	            }
155	        }
156	        groupScoresFp32.SetValue(g, best1 + best2);
157	    }
158	}
159	
160	/* ================================================================
161	 * ComputeGroupScoresHalfBf16: half/bf16 path
162	 *
163	 * Principle: find top-2 in float32 (ordering preserved),
164	 * sum in float32, then cast to native T for correct rounding,
165	 * then cast back to float32 for top-4 selection.
166	 * ================================================================ */
167	template<typename T>
168	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::ComputeGroupScoresHalfBf16(
169	    LocalTensor<float>& sfp32, LocalTensor<T>& inputT,
170	    LocalTensor<float>& groupScoresFp32, LocalTensor<T>& groupScoresT)
171	{
172	    for (int32_t g = 0; g < N_GROUP; ++g) {
173	        int32_t base = g * EXPERTS_PER_GROUP;
174	        // Find top-2 using float32 values (ordering is identical to T ordering)
175	        float best1 = -3.402823466e+38f;
176	        float best2 = -3.402823466e+38f;
177	        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
178	            float v = sfp32.GetValue(base + i);
179	            if (v > best1) {
180	                best2 = best1;
181	                best1 = v;
182	            } else if (v > best2) {
183	                best2 = v;
184	            }
185	        }
186	        // Sum in float32
187	        float sumFp32 = best1 + best2;
188	        // Cast to T and back to float32 for native T precision rounding
189	        T sumT = static_cast<T>(sumFp32);
190	        groupScoresT.SetValue(g, sumT);
191	        groupScoresFp32.SetValue(g, static_cast<float>(sumT));
192	    }
193	}
194	
195	/* ================================================================
196	 * Compute: main computation per row
197	 *
198	 * Float32 path: all computation in float32.
199	 * Half/bf16 path: group top-2 sum uses native T rounding,
200	 *   rest in float32.
201	 * ================================================================ */
202	template<typename T>
203	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Compute(
204	    int32_t tokenIdx)
205	{
206	    (void)tokenIdx;
207	    LocalTensor<T> inLocal = inQueue.DeQue<T>();
208	
209	    // Get float32 working buffers from calcBuf
210	    // calcBuf elements are floats
211	    LocalTensor<float> bufFp32 = calcBuf.Get<float>(1088);
212	
213	    constexpr int32_t OFF_SFP32 = 0;
214	    constexpr int32_t OFF_OUTFP32 = NUM_EXPERTS;               // 256
215	    constexpr int32_t OFF_GSFP32 = OFF_OUTFP32 + NUM_EXPERTS;  // 512
216	    constexpr int32_t OFF_GMFP32 = OFF_GSFP32 + 8;             // 520
217	    constexpr int32_t OFF_EXPMASK = OFF_GMFP32 + 8;            // 528
218	    constexpr int32_t OFF_TEMPFP32 = OFF_EXPMASK + NUM_EXPERTS; // 784
219	
220	    LocalTensor<float> sfp32 = bufFp32[OFF_SFP32];
221	    LocalTensor<float> outputFp32 = bufFp32[OFF_OUTFP32];
222	    LocalTensor<float> groupScoresFp32 = bufFp32[OFF_GSFP32];
223	    LocalTensor<float> groupMaskFp32 = bufFp32[OFF_GMFP32];
224	    LocalTensor<float> expandedMaskFp32 = bufFp32[OFF_EXPMASK];
225	    LocalTensor<float> tempFp32 = bufFp32[OFF_TEMPFP32];
226	
227	    // Cast input to float32 for computation
228	    Cast(sfp32, inLocal, AscendC::RoundMode::CAST_NONE, NUM_EXPERTS);
229	
230	    // ============================================================
231	    // Group top-2 + sum
232	    // ============================================================
233	    if constexpr (std::is_same_v<T, float>) {
234	        // float32: direct computation
235	        ComputeGroupScoresFloat32(sfp32, groupScoresFp32);
236	    } else {
237	        // half/bf16: native T rounding for group scores
238	        // Use the inLocal (native T buffer) as the T workspace for group scores
239	        LocalTensor<T> groupScoresT = inLocal; // reuse inLocal buffer (only need 8 T elements)
240	        ComputeGroupScoresHalfBf16(sfp32, inLocal, groupScoresFp32, groupScoresT);
241	    }
242	
243	    // ============================================================
244	    // Top-4 groups from 8 group scores (float32)
245	    // ============================================================
246	    bool selected[N_GROUP] = {false, false, false, false, false, false, false, false};
247	    for (int32_t k = 0; k < TOPK_GROUP; ++k) {
248	        float bestVal = -3.402823466e+38f;
249	        int32_t bestIdx = 0;
250	        for (int32_t g = 0; g < N_GROUP; ++g) {
251	            if (selected[g]) continue;
252	            float v = groupScoresFp32.GetValue(g);
253	            if (v > bestVal) { bestVal = v; bestIdx = g; }
254	        }
255	        selected[bestIdx] = true;
256	    }
257	
258	    // ============================================================
259	    // Build group mask (8,) and expanded score mask (256,)
260	    // ============================================================
261	    Duplicate(groupMaskFp32, 0.0f, N_GROUP);
262	    Duplicate(expandedMaskFp32, 0.0f, NUM_EXPERTS);
263	    for (int32_t g = 0; g < N_GROUP; ++g) {
264	        if (selected[g]) {
265	            groupMaskFp32.SetValue(g, 1.0f);
266	            int32_t start = g * EXPERTS_PER_GROUP;
267	            int32_t end = start + EXPERTS_PER_GROUP;
268	            for (int32_t i = start; i < end; ++i) {
269	                expandedMaskFp32.SetValue(i, 1.0f);
270	            }
271	        }
272	    }
273	
274	    // ============================================================
275	    // Masked fill: output = expandedMask ? sfp32 : -inf
276	    // ============================================================
277	    constexpr float NEG_INF_FP32 = -3.402823466e+38f;
278	
279	    // Build masked output: if mask == 1, use score; else use -inf
280	    for (int32_t i = 0; i < NUM_EXPERTS; ++i) {
281	        float maskVal = expandedMaskFp32.GetValue(i);
282	        if (maskVal > 0.5f) {
283	            outputFp32.SetValue(i, sfp32.GetValue(i));
284	        } else {
285	            outputFp32.SetValue(i, NEG_INF_FP32);
286	        }
287	    }
288	
289	    // ============================================================
290	    // Write outputs to TQue
291	    // ============================================================
292	    if constexpr (std::is_same_v<T, float>) {
293	        // float32: direct copy
294	        LocalTensor<float> outScoreLocal = outQueueScore.AllocTensor<float>();
295	        DataCopy(outScoreLocal, outputFp32, NUM_EXPERTS);
296	        outQueueScore.EnQue(outScoreLocal);
297	
298	        LocalTensor<float> outMaskLocal = outQueueMask.AllocTensor<float>();
299	        DataCopy(outMaskLocal, groupMaskFp32, N_GROUP);
300	        outQueueMask.EnQue(outMaskLocal);
301	
302	        inQueue.FreeTensor(inLocal);
303	    } else {
304	        // half/bf16: cast back to T, then enqueue
305	        LocalTensor<T> outScoreLocal = outQueueScore.AllocTensor<T>();
306	        Cast(outScoreLocal, outputFp32, AscendC::RoundMode::CAST_NONE, NUM_EXPERTS);
307	        outQueueScore.EnQue(outScoreLocal);
308	
309	        LocalTensor<T> outMaskLocal = outQueueMask.AllocTensor<T>();
310	        Cast(outMaskLocal, groupMaskFp32, AscendC::RoundMode::CAST_NONE, N_GROUP);
311	        outQueueMask.EnQue(outMaskLocal);
312	
313	        inQueue.FreeTensor(inLocal);
314	    }
315	}
316	
317	/* ================================================================
318	 * CopyOut: write one row in native dtype T
319	 * ================================================================ */
320	template<typename T>
321	__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::CopyOut(
322	    int32_t tokenIdx)
323	{
324	    int64_t offS = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
325	    int64_t offM = static_cast<int64_t>(tokenIdx) * N_GROUP;
326	
327	    LocalTensor<T> outScoreLocal = outQueueScore.DeQue<T>();
328	    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)), 0, 0, 0};
329	    DataCopyPad(maskedScoresGm[offS], outScoreLocal, cp);
330	    outQueueScore.FreeTensor(outScoreLocal);
331	
332	    LocalTensor<T> outMaskLocal = outQueueMask.DeQue<T>();
333	    DataCopyExtParams mcp{1, static_cast<uint32_t>(N_GROUP * sizeof(T)), 0, 0, 0};
334	    DataCopyPad(groupMaskOutGm[offM], outMaskLocal, mcp);
335	    outQueueMask.FreeTensor(outMaskLocal);
336	}
337	
338	/* ================================================================
339	 * Kernel entry points - one per dtype
340	 * ================================================================ */
341	
342	extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking_float(
343	    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
344	    GM_ADDR tiling)
345	{
346	    TPipe pipe;
347	    KernelMoeGroupScoreAggregationAndMasking<float> op;
348	    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
349	    op.Process();
350	    pipe.Destroy();
351	}
352	
353	extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking_half(
354	    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
355	    GM_ADDR tiling)
356	{
357	    TPipe pipe;
358	    KernelMoeGroupScoreAggregationAndMasking<half> op;
359	    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
360	    op.Process();
361	    pipe.Destroy();
362	}
363	
364	extern "C" __global__ __aicore__ void moe_group_score_aggregation_and_masking_bfloat16(
365	    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
366	    GM_ADDR tiling)
367	{
368	    TPipe pipe;
369	    KernelMoeGroupScoreAggregationAndMasking<bfloat16_t> op;
370	    op.Init(scores, maskedScores, groupMaskOut, tiling, &pipe);
371	    op.Process();
372	    pipe.Destroy();
373	}
