{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under CANN Open Software License Agreement Version 2.0.
 *
 * MoE Group Score Aggregation and Masking Kernel (v2)
 *
 * Template-based kernel supporting float32, float16 (half), and bfloat16.
 *
 * Key design:
 *  - float32: all computation in float32.
 *  - half: Cast input to float32 (supported on AIC), compute with half-precision
 *    rounding for group scores, Cast output back to half.
 *  - bfloat16: avoid AscendC::Cast entirely (not supported on AIV).
 *    Work directly in bfloat16_t for group top-2 and output.
 *    Use scalar conversion bf16<->fp32 for group score transfer.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t NUM_EXPERTS = 256;
constexpr int32_t N_GROUP = 8;
constexpr int32_t TOPK_GROUP = 4;
constexpr int32_t EXPERTS_PER_GROUP = 32;

/* Tiling: packed struct passed from host via GM */
struct MoERoutingTiling {
    int32_t numTokens;
    int32_t rowsPerCore;
};

template<typename T>
class KernelMoeGroupScoreAggregationAndMasking {
public:
    __aicore__ inline KernelMoeGroupScoreAggregationAndMasking() {}
    __aicore__ inline void Init(
        GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
        GM_ADDR tilingGM, TPipe* tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int32_t tokenIdx);
    __aicore__ inline void Compute(int32_t tokenIdx);
    __aicore__ inline void CopyOut(int32_t tokenIdx);

    // Per-dtype compute implementations
    __aicore__ inline void ComputeFloat32(LocalTensor<float>& inLocalFp32);
    __aicore__ inline void ComputeHalf(LocalTensor<half>& inLocalHalf);
    __aicore__ inline void ComputeBf16(LocalTensor<bfloat16_t>& inLocalBf16);

    GlobalTensor<T> scoresGm;
    GlobalTensor<T> maskedScoresGm;
    GlobalTensor<T> groupMaskOutGm;

    int32_t numTokens;
    int32_t rowsPerCore;

    TQue<QuePosition::VECIN, 1> inQueue;
    TQue<QuePosition::VECOUT, 1> outQueueScore;
    TQue<QuePosition::VECOUT, 1> outQueueMask;
    TBuf<TPosition::VECCALC> calcBuf;
    TPipe* pipe;
};

/* ================================================================
 * Init
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Init(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tilingGM, TPipe* tPipe)
{
    this->pipe = tPipe;
    auto* gt = reinterpret_cast<__gm__ MoERoutingTiling*>(tilingGM);
    this->numTokens = gt->numTokens;
    this->rowsPerCore = gt->rowsPerCore;

    scoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(scores),
                              static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    maskedScoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(maskedScores),
                                    static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    groupMaskOutGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(groupMaskOut),
                                    static_cast<int64_t>(numTokens) * N_GROUP);

    pipe->InitBuffer(inQueue, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)));
    pipe->InitBuffer(outQueueScore, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)));
    pipe->InitBuffer(outQueueMask, 1, static_cast<uint32_t>(N_GROUP * sizeof(T)));

    // calcBuf sized for worst case (float32 computation buffer)
    // Layout: [input_fp32(256)] [output_fp32(256)] [groupScores(8)]
    //         [groupMask(8)] [expandedMask(256)] [temp(264)]
    // Total: ~1048 floats, pad to 1088
    constexpr int32_t FP32_ELEMS = 1088;
    pipe->InitBuffer(calcBuf, static_cast<uint32_t>(FP32_ELEMS * sizeof(float) + 256));
}

/* ================================================================
 * Process
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Process()
{
    int32_t coreIdx = static_cast<int32_t>(GetBlockIdx());
    for (int32_t localIdx = 0; localIdx < rowsPerCore; ++localIdx) {
        int32_t tokenIdx = coreIdx * rowsPerCore + localIdx;
        if (tokenIdx >= numTokens) break;
        CopyIn(tokenIdx);
        Compute(tokenIdx);
        CopyOut(tokenIdx);
    }
}

/* ================================================================
 * CopyIn
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::CopyIn(
    int32_t tokenIdx)
{
    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
    int64_t offset = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
    DataCopyPad(inLocal, scoresGm[offset], cp, pp);
    inQueue.EnQue(inLocal);
}

/* ================================================================
 * ComputeFloat32: float32 path
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::ComputeFloat32(
    LocalTensor<float>& inLocalFp32)
{
    // Get float32 working buffers from calcBuf
    LocalTensor<float> bufFp32 = calcBuf.Get<float>(1088);

    constexpr int32_t OFF_SFP32 = 0;
    constexpr int32_t OFF_OUTFP32 = NUM_EXPERTS;
    constexpr int32_t OFF_GSFP32 = OFF_OUTFP32 + NUM_EXPERTS;
    constexpr int32_t OFF_GMFP32 = OFF_GSFP32 + 8;
    constexpr int32_t OFF_EXPMASK = OFF_GMFP32 + 8;

    LocalTensor<float> sfp32 = bufFp32[OFF_SFP32];
    LocalTensor<float> outputFp32 = bufFp32[OFF_OUTFP32];
    LocalTensor<float> groupScoresFp32 = bufFp32[OFF_GSFP32];
    LocalTensor<float> groupMaskFp32 = bufFp32[OFF_GMFP32];
    LocalTensor<float> expandedMaskFp32 = bufFp32[OFF_EXPMASK];

    // Copy input (already float32)
    DataCopy(sfp32, inLocalFp32, NUM_EXPERTS);

    // Group top-2 in float32
    for (int32_t g = 0; g < N_GROUP; ++g) {
        int32_t base = g * EXPERTS_PER_GROUP;
        float best1 = -3.402823466e+38f;
        float best2 = -3.402823466e+38f;
        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
            float v = sfp32.GetValue(base + i);
            if (v > best1) { best2 = best1; best1 = v; }
            else if (v > best2) { best2 = v; }
        }
        groupScoresFp32.SetValue(g, best1 + best2);
    }

    // Top-4 groups
    bool selected[N_GROUP] = {false, false, false, false, false, false, false, false};
    for (int32_t k = 0; k < TOPK_GROUP; ++k) {
        float bestVal = -3.402823466e+38f;
        int32_t bestIdx = 0;
        for (int32_t g = 0; g < N_GROUP; ++g) {
            if (selected[g]) continue;
            float v = groupScoresFp32.GetValue(g);
            if (v > bestVal) { bestVal = v; bestIdx = g; }
        }
        selected[bestIdx] = true;
    }

    // Build masks
    Duplicate(groupMaskFp32, 0.0f, N_GROUP);
    Duplicate(expandedMaskFp32, 0.0f, NUM_EXPERTS);
    for (int32_t g = 0; g < N_GROUP; ++g) {
        if (selected[g]) {
            groupMaskFp32.SetValue(g, 1.0f);
            int32_t start = g * EXPERTS_PER_GROUP;
            int32_t end = start + EXPERTS_PER_GROUP;
            for (int32_t i = start; i < end; ++i) {
                expandedMaskFp32.SetValue(i, 1.0f);
            }
        }
    }

    // Masked fill
    constexpr float NEG_INF = -3.402823466e+38f;
    for (int32_t i = 0; i < NUM_EXPERTS; ++i) {
        float maskVal = expandedMaskFp32.GetValue(i);
        outputFp32.SetValue(i, (maskVal > 0.5f) ? sfp32.GetValue(i) : NEG_INF);
    }

    // Write float32 output
    LocalTensor<float> outScoreLocal = outQueueScore.AllocTensor<float>();
    DataCopy(outScoreLocal, outputFp32, NUM_EXPERTS);
    outQueueScore.EnQue(outScoreLocal);

    LocalTensor<float> outMaskLocal = outQueueMask.AllocTensor<float>();
    DataCopy(outMaskLocal, groupMaskFp32, N_GROUP);
    outQueueMask.EnQue(outMaskLocal);

    inQueue.FreeTensor(inLocalFp32);
}

/* ================================================================
 * ComputeHalf: half path - use Cast (supported on AIC)
 *
 * Cast input half->fp32, compute group scores with half precision
 * rounding, then Cast output fp32->half.
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::ComputeHalf(
    LocalTensor<half>& inLocalHalf)
{
    LocalTensor<float> bufFp32 = calcBuf.Get<float>(1088);

    constexpr int32_t OFF_SFP32 = 0;
    constexpr int32_t OFF_OUTFP32 = NUM_EXPERTS;
    constexpr int32_t OFF_GSFP32 = OFF_OUTFP32 + NUM_EXPERTS;
    constexpr int32_t OFF_GMFP32 = OFF_GSFP32 + 8;
    constexpr int32_t OFF_EXPMASK = OFF_GMFP32 + 8;
    constexpr int32_t OFF_GSTEMP = OFF_EXPMASK + NUM_EXPERTS;

    LocalTensor<float> sfp32 = bufFp32[OFF_SFP32];
    LocalTensor<float> outputFp32 = bufFp32[OFF_OUTFP32];
    LocalTensor<float> groupScoresFp32 = bufFp32[OFF_GSFP32];
    LocalTensor<float> groupMaskFp32 = bufFp32[OFF_GMFP32];
    LocalTensor<float> expandedMaskFp32 = bufFp32[OFF_EXPMASK];
    LocalTensor<half> groupScoresHalf = bufFp32[OFF_GSTEMP].ReinterpretCast<half>();

    // Cast half -> float32
    Cast(sfp32, inLocalHalf, AscendC::RoundMode::CAST_NONE, NUM_EXPERTS);

    // Group top-2: find in float32, sum in float32,
    // round to half for native precision, then back to float32
    for (int32_t g = 0; g < N_GROUP; ++g) {
        int32_t base = g * EXPERTS_PER_GROUP;
        float best1 = -65504.0f;   // half min
        float best2 = -65504.0f;
        for (int32_t i = 0; i < EXPERTS_PER_GROUP; ++i) {
            float v = sfp32.GetValue(base + i);
            if (v > best1) { best2 = best1; best1 = v; }
            else if (v > best2) { best2 = v; }
        }
        float sumFp32 = best1 + best2;
        // Round to half precision, then back to float32
        half sumHalf = static_cast<half>(sumFp32);
        groupScoresHalf.SetValue(g, sumHalf);
        groupScoresFp32.SetValue(g, static_cast<float>(sumHalf));
    }

    // Top-4 groups from float32 group scores
    bool selected[N_GROUP] = {false, false, false, false, false, false, false, false};
    for (int32_t k = 0; k < TOPK_GROUP; ++k) {
        float bestVal = -3.402823466e+38f;
        int32_t bestIdx = 0;
        for (int32_t g = 0; g < N_GROUP; ++g) {
            if (selected[g]) continue;
            float v = groupScoresFp32.GetValue(g);
            if (v > bestVal) { bestVal = v; bestIdx = g; }
        }
        selected[bestIdx] = true;
    }

    // Build masks (float32)
    Duplicate(groupMaskFp32, 0.0f, N_GROUP);
    Duplicate(expandedMaskFp32, 0.0f, NUM_EXPERTS);
    for (int32_t g = 0; g < N_GROUP; ++g) {
        if (selected[g]) {
            groupMaskFp32.SetValue(g, 1.0f);
            int32_t start = g * EXPERTS_PER_GROUP;
            int32_t end = start + EXPERTS_PER_GROUP;
            for (int32_t i = start; i < end; ++i) {
                expandedMaskFp32.SetValue(i, 1.0f);
            }
        }
    }

    // Masked fill in float32
    constexpr float NEG_INF = -3.402823466e+38f;
    for (int32_t i = 0; i < NUM_EXPERTS; ++i) {
        float maskVal = expandedMaskFp32.GetValue(i);
        outputFp32.SetValue(i, (maskVal > 0.5f) ? sfp32.GetValue(i) : NEG_INF);
    }

    // Cast float32 -> half for output
    LocalTensor<half> outScoreLocal = outQueueScore.AllocTensor<half>();
    Cast(outScoreLocal, outputFp32, AscendC::RoundMode::CAST_NONE, NUM_EXPERTS);
    outQueueScore.EnQue(outScoreLocal);

    LocalTensor<half> outMaskLocal = outQueueMask.AllocTensor<half>();
    Cast(outMaskLocal, groupMaskFp32, AscendC::RoundMode::CAST_NONE, N_GROUP);
    outQueueMask.EnQue(outMaskLocal);

    inQueue.FreeTensor(inLocalHalf);
}

/* ================================================================
 * ComputeBf16: bfloat16 path - avoid AscendC::Cast entirely
 *
 * AIV does not support bf16 Cast. Work directly in bfloat16_t.
 * Group top-2 and sum in native bf16. Convert group scores
 * to float32 scalarly for top-4 selection.
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::ComputeBf16(
    LocalTensor<bfloat16_t>& inLocalBf16)
{
    LocalTensor<float> bufFp32 = calcBuf.Get<float>(1088);

    constexpr int32_t OFF_GSFP32 = 0;
    constexpr int32_t OFF_GMFP32 = OFF_GSFP32 + 8;
    constexpr int32_t OFF_EXPMASK = OFF_GMFP32 + 8;
    constexpr int32_t OFF_OUTBF16 = OFF_EXPMASK + NUM_EXPERTS;

    LocalTensor<float> groupScoresFp32 = bufFp32[OFF_GSFP32];
    LocalTensor<float> groupMaskFp32 = bufFp32[OFF_GMFP32];
