 *
 * MoE Group Score Aggregation and Masking Kernel (v2)
 *
 * Template-based kernel supporting float32 and float16 (half).
 * bfloat16 is handled via uint16_t bit-level conversion to avoid
 * bfloat16_t arithmetic/type-cast limitations on AscendC.
 */

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t NUM_EXPERTS = 256;
constexpr int32_t N_GROUP = 8;
constexpr int32_t TOPK_GROUP = 4;
constexpr int32_t EXPERTS_PER_GROUP = 32;

/* Tiling: packed struct passed from host via GM */
struct MoERoutingTiling {
    int32_t numTokens;
    int32_t rowsPerCore;
};

/* ================================================================
 * bfloat16 bit-level conversion helpers
 *
 * bf16 layout: 1 sign | 8 exponent | 7 mantissa
 * float32 layout: 1 sign | 8 exponent | 23 mantissa
 *
 * bf16 -> float32: left shift by 16 (puts mantissa in top 7 of 23 bits)
 * float32 -> bf16: round bits 15:0, return top 16 bits
 * ================================================================ */

// Volatile union to avoid strict-aliasing issues on AscendC
__aicore__ inline float bf16U16ToFloat(uint16_t bf16Bits)
{
    uint32_t bits = static_cast<uint32_t>(bf16Bits) << 16;
    volatile union { uint32_t u; float f; } conv;
    conv.u = bits;
    return conv.f;
}

__aicore__ inline uint16_t floatToBf16U16(float val)
{
    volatile union { float f; uint32_t u; } conv;
    conv.f = val;
    uint32_t bits = conv.u;
    // Round to nearest even for the lower 16 bits
    uint32_t lsb = (bits >> 16) & 1U;
    uint32_t round_bit = (bits >> 15) & 1U;
    uint32_t sticky = (bits & 0x7FFFU);
    if (round_bit && (sticky || lsb)) {
        bits += (1U << 16);
    }
    return static_cast<uint16_t>(bits >> 16);
}

__aicore__ inline float floatRoundToBf16(float val)
{
    return bf16U16ToFloat(floatToBf16U16(val));
}

/* ================================================================
 * Kernel template - float32 and half
 * ================================================================ */
template<typename T>
class KernelMoeGroupScoreAggregationAndMasking {
public:
    __aicore__ inline KernelMoeGroupScoreAggregationAndMasking() {}
    __aicore__ inline void Init(
        GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
        GM_ADDR tilingGM, TPipe* tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int32_t tokenIdx);
    __aicore__ inline void Compute(int32_t tokenIdx);
    __aicore__ inline void CopyOut(int32_t tokenIdx);

    GlobalTensor<T> scoresGm;
    GlobalTensor<T> maskedScoresGm;
    GlobalTensor<T> groupMaskOutGm;

    int32_t numTokens;
    int32_t rowsPerCore;

    TQue<QuePosition::VECIN, 1> inQueue;
    TQue<QuePosition::VECOUT, 1> outQueueScore;
    TQue<QuePosition::VECOUT, 1> outQueueMask;
    TBuf<TPosition::VECCALC> calcBuf;
    TPipe* pipe;
};

/* ================================================================
 * Bfloat16 kernel (uses uint16_t, not bfloat16_t)
 * ================================================================ */
class KernelMoeGroupScoreAggregationAndMaskingBf16 {
public:
    __aicore__ inline KernelMoeGroupScoreAggregationAndMaskingBf16() {}
    __aicore__ inline void Init(
        GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
        GM_ADDR tilingGM, TPipe* tPipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int32_t tokenIdx);
    __aicore__ inline void Compute(int32_t tokenIdx);
    __aicore__ inline void CopyOut(int32_t tokenIdx);

    // Use uint16_t for bf16 storage (same size as bfloat16_t, no type issues)
    GlobalTensor<uint16_t> scoresGm;
    GlobalTensor<uint16_t> maskedScoresGm;
    GlobalTensor<uint16_t> groupMaskOutGm;

    int32_t numTokens;
    int32_t rowsPerCore;

    TQue<QuePosition::VECIN, 1> inQueue;
    TQue<QuePosition::VECOUT, 1> outQueueScore;
    TQue<QuePosition::VECOUT, 1> outQueueMask;
    TBuf<TPosition::VECCALC> calcBuf;
    TPipe* pipe;
};

/* ================================================================
 * Template Init
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Init(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tilingGM, TPipe* tPipe)
{
    this->pipe = tPipe;
    auto* gt = reinterpret_cast<__gm__ MoERoutingTiling*>(tilingGM);
    this->numTokens = gt->numTokens;
    this->rowsPerCore = gt->rowsPerCore;

    scoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(scores),
                              static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    maskedScoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(maskedScores),
                                    static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    groupMaskOutGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(groupMaskOut),
                                    static_cast<int64_t>(numTokens) * N_GROUP);

    pipe->InitBuffer(inQueue, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)));
    pipe->InitBuffer(outQueueScore, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)));
    pipe->InitBuffer(outQueueMask, 1, static_cast<uint32_t>(N_GROUP * sizeof(T)));

    constexpr int32_t FP32_ELEMS = 1088;
    pipe->InitBuffer(calcBuf, static_cast<uint32_t>(FP32_ELEMS * sizeof(float) + 256));
}

/* ================================================================
 * Bf16 Init - uses uint16_t for storage
 * ================================================================ */
__aicore__ inline void KernelMoeGroupScoreAggregationAndMaskingBf16::Init(
    GM_ADDR scores, GM_ADDR maskedScores, GM_ADDR groupMaskOut,
    GM_ADDR tilingGM, TPipe* tPipe)
{
    this->pipe = tPipe;
    auto* gt = reinterpret_cast<__gm__ MoERoutingTiling*>(tilingGM);
    this->numTokens = gt->numTokens;
    this->rowsPerCore = gt->rowsPerCore;

    scoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ uint16_t*>(scores),
                              static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    maskedScoresGm.SetGlobalBuffer(reinterpret_cast<__gm__ uint16_t*>(maskedScores),
                                    static_cast<int64_t>(numTokens) * NUM_EXPERTS);
    groupMaskOutGm.SetGlobalBuffer(reinterpret_cast<__gm__ uint16_t*>(groupMaskOut),
                                    static_cast<int64_t>(numTokens) * N_GROUP);

    pipe->InitBuffer(inQueue, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(uint16_t)));
    pipe->InitBuffer(outQueueScore, 1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(uint16_t)));
    pipe->InitBuffer(outQueueMask, 1, static_cast<uint32_t>(N_GROUP * sizeof(uint16_t)));

    constexpr int32_t FP32_ELEMS = 1088;
    pipe->InitBuffer(calcBuf, static_cast<uint32_t>(FP32_ELEMS * sizeof(float) + 512));
}

/* ================================================================
 * Template Process / CopyIn / CopyOut
 * ================================================================ */
template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Process()
{
    int32_t coreIdx = static_cast<int32_t>(GetBlockIdx());
    for (int32_t localIdx = 0; localIdx < rowsPerCore; ++localIdx) {
        int32_t tokenIdx = coreIdx * rowsPerCore + localIdx;
        if (tokenIdx >= numTokens) break;
        CopyIn(tokenIdx);
        Compute(tokenIdx);
        CopyOut(tokenIdx);
    }
}

template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::CopyIn(
    int32_t tokenIdx)
{
    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
    int64_t offset = static_cast<int64_t>(tokenIdx) * NUM_EXPERTS;
    DataCopyExtParams cp{1, static_cast<uint32_t>(NUM_EXPERTS * sizeof(T)), 0, 0, 0};
    DataCopyPadExtParams<T> pp{false, 0, 0, 0};
    DataCopyPad(inLocal, scoresGm[offset], cp, pp);
    inQueue.EnQue(inLocal);
}

template<typename T>
__aicore__ inline void KernelMoeGroupScoreAggregationAndMasking<T>::Compute(
    int32_t tokenIdx)
{
    (void)tokenIdx;
    LocalTensor<T> inLocal = inQueue.DeQue<T>();

    // Float32 working buffers
    LocalTensor<float> bufFp32 = calcBuf.Get<float>(1088);
    constexpr int32_t OFF_SFP32 = 0;
    constexpr int32_t OFF_OUTFP32 = NUM_EXPERTS;
    constexpr int32_t OFF_GSFP32 = OFF_OUTFP32 + NUM_EXPERTS;
    constexpr int32_t OFF_GMFP32 = OFF_GSFP32 + 8;
    constexpr int32_t OFF_EXPMASK = OFF_GMFP32 + 8;

